// Framework mapping (CLI-INV-65, docs/plans/framework-map-spec.md): the criteria each Audit room
// control gives evidence toward. This table is the single home of the mapping; the Audit room, the
// transcript and docs/compliance/FRAMEWORK-MAP.md (generated by TestFrameworkMapDoc) all read it.
// Every entry is "maps to", never "complies with": whether a criterion is met is the auditor's call.

// The four frameworks, in display order.
const (
	fwSOC2  = "SOC 2"
	fwISO   = "ISO 27001"
	fwSSDF  = "NIST SSDF"
	fwEUAIA = "EU AI Act"
)

type framework struct {
	Name, Version, Note string
}

var frameworks = []framework{
	{fwSOC2, "AICPA Trust Services Criteria, 2017, with the 2022 revised points of focus", ""},
	{fwISO, "ISO/IEC 27001:2022, Annex A", ""},
	{fwSSDF, "NIST SP 800-218, Secure Software Development Framework v1.1 (February 2022)", ""},
	{fwEUAIA, "Regulation (EU) 2024/1689", "Only for a provider of a high-risk AI system whose code agents help write. Art. 12 (record-keeping) and Art. 14 (human oversight) concern the high-risk system's own logs and oversight, not the tools used to build it, so no control maps to them."},
}

// frameworkRef is what the transcript carries for each mapped criterion.
type frameworkRef struct {
	Framework string `json:"framework"`
	Criterion string `json:"criterion"`
}

type frameworkEntry struct {
	frameworkRef
	Reason string
}

func fe(fw, criterion, reason string) frameworkEntry {
	return frameworkEntry{frameworkRef{fw, criterion}, reason}
}

