// mapsTo returns a control's mapped criteria, in table order, for the transcript.
func mapsTo(id string) []frameworkRef {
	refs := []frameworkRef{}
	for _, e := range frameworkMap[id] {
		refs = append(refs, e.frameworkRef)
	}
	return refs
}

const frameworkCaveat = "\"Maps to\" (evidence toward) names the criteria a control gives evidence toward. It is not a statement that any criterion is met: that is the auditor's judgment, and each criterion needs more than this evidence."

const frameworkDocURL = "https://github.com/kamisrini/proofbound/blob/main/docs/compliance/FRAMEWORK-MAP.md"

// frameworkDoc renders docs/compliance/FRAMEWORK-MAP.md from the table (TestFrameworkMapDoc).
func frameworkDoc() string {
	var controls []auditControl
	for i := 1; i <= len(controlQuestions); i++ {
		id := fmt.Sprintf("C%d", i)
		controls = append(controls, auditControl{ID: id, Question: controlQuestions[id]})
	}
	var b strings.Builder
	b.WriteString("<!-- @generated by `cd kernel && go test ./internal/cli -run TestFrameworkMapDoc -update`; do not hand-edit -->\n\n")
	b.WriteString("# What the Audit room's controls map to\n\n")
	b.WriteString("Each control in `proofbound ui` (the Audit room) answers one question about a range of commits, with the\n")
	b.WriteString("evidence and the command that reproduces it. This page lists the framework criteria each answer gives\n")
	b.WriteString("evidence toward. The same mapping is on each control card and in the audit transcript (`maps_to`).\n\n")
	b.WriteString("> " + frameworkCaveat + " An empty cell means no claim, not that the framework is silent.\n\n")
	b.WriteString("## Frameworks and versions\n\n| Framework | Version | Scope note |\n|---|---|---|\n")
	for _, f := range frameworks {
		note := f.Note
		if note == "" {
			note = "—"
		}
		fmt.Fprintf(&b, "| %s | %s | %s |\n", f.Name, f.Version, note)
	}
	b.WriteString("\n## Summary\n\n| Control | Question |")
	for _, f := range frameworks {
		b.WriteString(" " + f.Name + " |")
	}
	b.WriteString("\n|---|---|" + strings.Repeat("---|", len(frameworks)) + "\n")
	for _, c := range controls {
		fmt.Fprintf(&b, "| %s | %s |", c.ID, c.Question)
		for _, f := range frameworks {
			var ids []string
			for _, e := range frameworkMap[c.ID] {
				if e.Framework == f.Name {
					ids = append(ids, e.Criterion)
				}
			}
			if len(ids) == 0 {
				b.WriteString(" — |")
			} else {
				b.WriteString(" " + strings.Join(ids, ", ") + " |")
			}
		}
		b.WriteString("\n")
	}
	b.WriteString("\n## Why each entry\n")
	for _, c := range controls {
		fmt.Fprintf(&b, "\n### %s: %s\n\n", c.ID, c.Question)
		for _, e := range frameworkMap[c.ID] {
			fmt.Fprintf(&b, "- **%s %s**: %s.\n", e.Framework, e.Criterion, e.Reason)
		}
	}
	b.WriteString("\n## Agents\n\n")
	b.WriteString("Git records who made a commit as typed text, and an agent's commit is often authored by the person\n")
	b.WriteString("who ran it. The controls answer for agent work in five ways: C8 refuses a review by the change's\n")
	b.WriteString("author, any agent named on it or its spec owner; C10 names every line an agent changed outside the\n")
	b.WriteString("area its spec allowed; C2 lists agent code that claims no spec; and C9 binds a commit to a declared key\n")
	b.WriteString("when it is signed (`proofbound keys git-sign`); who held the key is outside that evidence. And C12\n")
	b.WriteString("names which recorded Claude Code sessions wrote a change's lines and which lines no recorded edit\n")
	b.WriteString("wrote, as the reviewer read the logs on the agent's machine.\n")
	return b.String()
}
